(()=>{var t={ice:5,hybrid:6,ev:9};var s=.65;function c(e,i){let o=Math.max(0,Math.min(100,Number(i)||0)),n=o/3.6/(Math.PI*s)*60;return{kmh:o,wheelRpm:n,rpm:n*t[e]}}var a={ice:{name:"Motore a benzina",short:"Termico",tag:"COMBUSTIONE INTERNA",subtitle:"4 cilindri in linea \xB7 ciclo Otto \xB7 2,0 L",icon:"fuel",color:"#678b89",nominal:110,maxRpm:6500,components:["cover","head","pistons","rods","crank","block","intake","exhaust","timing","sump"]},hybrid:{name:"Sistema full hybrid",short:"Ibrido",tag:"DUE FONTI, UN SISTEMA",subtitle:"Architettura parallela \xB7 termico + elettrico",icon:"combine",color:"#8eac60",nominal:130,maxRpm:6e3,components:["cover","head","pistons","rods","crank","block","intake","exhaust","timing","sump","motor","inverter","battery","transmission"]},ev:{name:"Motore elettrico",short:"Elettrico",tag:"TRAZIONE ELETTRICA",subtitle:"Sincrono a magneti permanenti \xB7 batteria 400 V",icon:"zap",color:"#8098c9",nominal:150,maxRpm:14e3,components:["housing","stator","rotor","shaft","bearings","inverter","battery","reducer"]}};var d={city:{name:"Citt\xE0",speed:30,demand:9,rpm:1800,load:35,ambient:20},mixed:{name:"Extraurbano",speed:70,demand:14,rpm:2800,load:50,ambient:20},highway:{name:"Autostrada",speed:100,demand:21,rpm:3800,load:70,ambient:25},climb:{name:"Salita impegnativa",speed:50,demand:30,rpm:4500,load:90,ambient:35}},l=2.35,m=8.9;var r=(e,i=2)=>new Intl.NumberFormat("it-IT",{maximumFractionDigits:i}).format(e),u=[["EPA \xB7 Emissioni di un veicolo","https://www.epa.gov/greenvehicles/greenhouse-gas-emissions-typical-passenger-vehicle","Costante di riferimento",`EPA indica 8.887 g di CO\u2082 per gallone USA di benzina. Dividendo per 3,78541 L otteniamo circa ${r(l)} kg/L, valore arrotondato usato qui. La composizione del carburante pu\xF2 variare. La pagina distingue inoltre emissioni allo scarico ed emissioni a monte.`],["DOE / AFDC \xB7 Propriet\xE0 dei carburanti","https://afdc.energy.gov/fuels/properties","Intervallo documentato",`Per benzina/E10, AFDC riporta un potere calorifico inferiore di 112.114\u2013116.090 Btu/gal: circa 8,68\u20138,99 kWh/L. Il laboratorio adotta ${r(m)} kWh/L come valore rappresentativo, non universale.`],["NIST \xB7 Conversione dell\u2019energia","https://www.nist.gov/glossary-term/19511","Conversioni","Riferimento per la conversione da Btu a joule: 1 Btu \u2248 1.055 J. Per esprimere l\u2019energia in kWh si usa inoltre 1 kWh = 3,6 MJ."],["DOE / EPA \xB7 Dove va l\u2019energia","https://www.fueleconomy.gov/feg/atv.shtml","Principi fisici","Descrive perdite termiche e meccaniche, resistenza al rotolamento, resistenza aerodinamica e recupero in frenata. Supporta le relazioni qualitative; i coefficienti di engineLab non sono presi da questo diagramma."],["DOE / AFDC \xB7 Come funziona un ibrido","https://afdc.energy.gov/vehicles/how-do-hybrid-electric-cars-work","Architettura e componenti","Riferimento per motore termico, motore elettrico, batteria e frenata rigenerativa. Il laboratorio rappresenta un\u2019architettura parallela semplificata; non tutte le auto ibride hanno questa disposizione."],["DOE / AFDC \xB7 Come funziona un\u2019elettrica","https://afdc.energy.gov/vehicles/how-do-all-electric-cars-work","Architettura e componenti","Riferimento per batteria, elettronica di potenza, motore di trazione e raffreddamento. La simulazione rappresenta una macchina sincrona a magneti permanenti, non tutte le possibili motorizzazioni."],["EPA \xB7 Inquinanti dei veicoli","https://www.epa.gov/greenvehicles/smog-vehicle-emissions","Limiti delle emissioni mostrate","CO\u2082 e inquinanti atmosferici non sono sinonimi. Qui calcoliamo solo la CO\u2082 allo scarico a partire dal carburante: non stimiamo CO, NOx, idrocarburi o particolato."]];document.querySelector("#reference-list").innerHTML=u.map(([e,i,o,n],p)=>`<article class="reference-card"><span>${String(p+1).padStart(2,"0")} / ${o}</span><h3><a href="${i}" target="_blank" rel="noopener noreferrer">${e} \u2197</a></h3><p>${n}</p></article>`).join("");var g=[["Energia in ingresso","E = D \xD7 (1 \u2212 recupero) \xF7 rendimento","D \xE8 la domanda alle ruote in kWh/100 km. Recupero e rendimento sono frazioni, non percentuali intere."],["Consumo benzina",`C = E \xF7 ${r(m)} kWh/L`,"Il risultato \xE8 in L/100 km. Nell\u2019elettrico E \xE8 gi\xE0 il consumo in kWh/100 km."],["Chilometri con un litro","km/L = 100 \xF7 C","Definito solo per un consumo positivo e una velocit\xE0 maggiore di zero."],["Litri ogni ora","L/h = C \xD7 km/h \xF7 100","Collega il consumo per distanza al consumo per tempo."],["CO\u2082 per chilometro",`g/km = C \xD7 ${r(l*10)}`,"Dal fattore kg/L a g/km, per un consumo C espresso in L/100 km."],["CO\u2082 ogni secondo",`g/s = L/h \xD7 ${r(l*1e3,0)} \xF7 3.600`,"La CO\u2082 totale integra questo flusso nel tempo. Nell\u2019elettrico la CO\u2082 allo scarico \xE8 zero."],["Potenza netta richiesta","kW = D \xD7 (1 \u2212 recupero) \xD7 km/h \xF7 100","\xC8 una media equivalente del percorso, distinta dalla potenza disponibile indicativa."],["Totali della prova","Distanza = \u222B velocit\xE0 \xD7 dt / 3.600","Tempo in secondi; carburante ed energia si integrano allo stesso modo dalle rispettive portate."]];document.querySelector("#formula-rows").innerHTML=g.map(e=>`<tr>${e.map((i,o)=>o?`<td>${i}</td>`:`<th scope="row">${i}</th>`).join("")}</tr>`).join("");document.querySelector("#motion-facts").innerHTML=`<article><span>Diametro di rotolamento</span><strong>${r(s)} m</strong><small>Ipotesi comune ai tre modelli</small></article><article><span>Rapporti totali fissi</span><strong>${t.ice}:1 / ${t.hybrid}:1 / ${t.ev}:1</strong><small>Termico / ibrido / elettrico \xB7 scelte didattiche</small></article>`;document.querySelector("#motion-example").innerHTML=`<table><caption>Esempio calcolato a 100 km/h</caption><thead><tr><th>Sistema</th><th>Giri ruote/min</th><th>Giri motore/min</th></tr></thead><tbody>${Object.entries(a).map(([e,i])=>{let o=c(e,100);return`<tr><th scope="row">${i.short}</th><td>${r(o.wheelRpm,0)}</td><td>${r(o.rpm,0)}</td></tr>`}).join("")}</tbody></table>`;document.querySelector("#scenario-rows").innerHTML=Object.values(d).map(e=>`<tr><th scope="row">${e.name}</th><td>${e.speed} km/h</td><td>${e.demand} kWh/100 km</td><td>${e.load}%</td></tr>`).join("");document.querySelector("#model-equations").innerHTML=`<p>l = carico / 100; r = rpm / regime massimo; a = temperatura ambiente; v = velocit\xE0; v\u2080 = velocit\xE0 di riferimento dello scenario.</p><div class="formula-block">Fattore velocit\xE0 = [0,55 + 0,45 \xD7 (v/70)\xB2] / [0,55 + 0,45 \xD7 (v\u2080/70)\xB2]<br>D = domanda scenario \xD7 fattore velocit\xE0 \xD7 (0,75 + 0,5l) \xD7 [1 + 0,004 \xD7 max(0; 20 \u2212 a)]<br>Penalit\xE0 termica p = 0,07 senza raffreddamento; altrimenti 0,001 \xD7 max(0; a \u2212 30)<br>\u03B7 termico = 0,22 + 0,13l \u2212 0,08(r \u2212 0,5)\xB2 \u2212 p<br>\u03B7 ibrido = 0,35 + 0,04l \u2212 0,04(r \u2212 0,5)\xB2 \u2212 p<br>\u03B7 elettrico = 0,92 \u2212 0,10(l \u2212 0,6)\xB2 \u2212 0,05r \u2212 p</div><p>I rendimenti \u03B7 sono limitati tra 0,14 e 0,95. Regimi massimi illustrativi: ${a.ice.maxRpm}, ${a.hybrid.maxRpm} e ${a.ev.maxRpm} rpm. Il rapporto fisso sotto il regime di minimo \xE8 solo una rappresentazione cinematica: non modella frizione o cambio.</p><div class="formula-block">T equilibrio termico/ibrido = 67 + 27l + 0,4a + 48 se manca il raffreddamento<br>T equilibrio elettrico = 35 + 43l + 0,3a + 55 se manca il raffreddamento<br>T(t) = T equilibrio + (T iniziale \u2212 T equilibrio) \xD7 exp(\u2212t / \u03C4)<br>Fattore freddo = 1 + 0,15 \xD7 clamp[(70 \u2212 T) / 50; 0; 1]</div><p>Il fattore freddo moltiplica il consumo di benzina; il rendimento istantaneo viene diviso per lo stesso fattore. \u03C4 = 90 s in marcia, 180 s da fermo. Il confronto non applica il fattore freddo. La soglia di allerta di 110 \xB0C \xE8 illustrativa e non sostituisce limiti del costruttore.</p><div class="formula-block">Potenza disponibile = nominale \xD7 l \xD7 min(1; 2,2r) \xD7 fattore termico<br>Coppia disponibile = potenza in kW \xD7 60.000 / (2\u03C0 \xD7 rpm)</div><p>Nominali illustrativi: ${a.ice.nominal} / ${a.hybrid.nominal} / ${a.ev.nominal} kW. Fattore termico: 1 con raffreddamento, 0,72 senza. Potenza disponibile e coppia sono esempi separati dalla domanda alle ruote: non costituiscono una mappa prestazionale validata.</p>`;})();
